import math

def test_symmetric_pair():
    v = solution.dominant_direction([[3, 1], [1, 3]])
    assert abs(abs(v[0]) - 0.70710678) < 1e-3
    assert abs(abs(v[1]) - 0.70710678) < 1e-3

def test_diagonal():
    v = solution.dominant_direction([[2, 0], [0, 5]])
    assert abs(abs(v[1]) - 1.0) < 1e-3

def test_unit_length():
    v = solution.dominant_direction([[4, 2], [2, 3]])
    assert abs(math.sqrt(sum(x * x for x in v)) - 1.0) < 1e-9

def test_empty_raises():
    try:
        solution.dominant_direction([])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_non_square_raises():
    try:
        solution.dominant_direction([[1, 2], [3]])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_no_mutation():
    A = [[3, 1], [1, 3]]
    solution.dominant_direction(A)
    assert A == [[3, 1], [1, 3]]
